corrected_code:
const formidable = require('formidable');

router.put('/contracts/:contractId/signed-copy', checkLegalAuth, (req, res) => {
  const { contractId } = req.params;
  const form = new formidable.IncomingForm({ uploadDir: '/tmp/legal_docs' });

  form.parse(req, async (err, fields, files) => {
    if (err) return res.status(500).json({ error: 'Form parsing failed' });

    const contract = await ContractAgreement.findOne({
      where: { id: contractId, signatoryEmail: req.user.email }
    });
    if (!contract) return res.status(403).json({ error: 'Forbidden: you are not an authorized signatory for this contract' });

    const targetPath = `/storage/contracts/${contractId}_signed.pdf`;
    fs.renameSync(files.signedPdf.filepath, targetPath);

    await contract.update({ signedPdfPath: targetPath, status: 'EXECUTED' });
    res.json({ success: true, contractId });
  });
});
